/// Per kind id, the stretches of its children its template indents one level, by their anchors.
pub static DEPTH_REGIONS: &[::sittir_core::trivia_table::DepthRegion] = &[
    ::sittir_core::trivia_table::DepthRegion { kind: KindId(209), open: ::sittir_core::trivia_table::DepthAnchor::After(&["{"]), close: ::sittir_core::trivia_table::DepthAnchor::Before(&["}"]) },
    ::sittir_core::trivia_table::DepthRegion { kind: KindId(227), open: ::sittir_core::trivia_table::DepthAnchor::After(&["{"]), close: ::sittir_core::trivia_table::DepthAnchor::Before(&["}"]) },
    ::sittir_core::trivia_table::DepthRegion { kind: KindId(228), open: ::sittir_core::trivia_table::DepthAnchor::After(&[":"]), close: ::sittir_core::trivia_table::DepthAnchor::End },
    ::sittir_core::trivia_table::DepthRegion { kind: KindId(229), open: ::sittir_core::trivia_table::DepthAnchor::After(&[":"]), close: ::sittir_core::trivia_table::DepthAnchor::End },
    ::sittir_core::trivia_table::DepthRegion { kind: KindId(286), open: ::sittir_core::trivia_table::DepthAnchor::After(&["{"]), close: ::sittir_core::trivia_table::DepthAnchor::Before(&["}"]) },
    ::sittir_core::trivia_table::DepthRegion { kind: KindId(321), open: ::sittir_core::trivia_table::DepthAnchor::After(&["{"]), close: ::sittir_core::trivia_table::DepthAnchor::Before(&["}"]) },
    ::sittir_core::trivia_table::DepthRegion { kind: KindId(367), open: ::sittir_core::trivia_table::DepthAnchor::After(&["{", "{|"]), close: ::sittir_core::trivia_table::DepthAnchor::Before(&["}", "|}"]) },
];

#[must_use]
pub fn spacing_text(kind: KindId) -> &'static str {
    match kind {
        KindId(180) => "",
        KindId(181) => " ",
        KindId(182) => "\t",
        KindId(183) => "\n",
        KindId(184) => "\n\n",
        KindId(185) => "\n\n\n",
        KindId(186) => "\n",
        KindId(187) => "\n",
        _ => "",
    }
}

#[must_use]
pub fn allowed(site: SiteId) -> &'static [KindId] {
    SPACING_SITES[site.index()].3
}

/// Every layout kind (each `_layout` member, the depth movers among them where the grammar has them), the domain of `spacing_text`.
pub const LAYOUT_KINDS: &[KindId] = &[KindId(180), KindId(181), KindId(182), KindId(183), KindId(184), KindId(185), KindId(186), KindId(187)];

/// The kind id the grammar gives each gap kind, by `LayoutKinds` bit.
pub const GAPS: &[(u8, KindId)] = &[(1, KindId(180)), (2, KindId(181)), (4, KindId(182)), (8, KindId(183)), (16, KindId(184)), (32, KindId(185))];

pub const WHITESPACE: ::sittir_core::render::WhitespaceTable = ::sittir_core::render::WhitespaceTable { text_of: spacing_text, indent: INDENT_KIND, dedent: DEDENT_KIND, leaf_edges: LEAF_EDGES, gaps: GAPS };

